var job = new Job
{
    Id = "job-1",
    Duration = TimeSpan.FromHours(1),
    RequiredSkill = "skill",
    Priority = 1
};
var anchor = new Slot { Start = new DateTime(2024, 1, 5, 9, 0, 0) };

var expanded = engine.Expand(job, anchor, 3);

Check.NotNull(expanded);
Check.Equal(3, expanded.Count);
Check.SequenceEqual(new[]
{
    new DateTime(2024, 1, 5, 9, 0, 0),
    new DateTime(2024, 1, 8, 9, 0, 0),
    new DateTime(2024, 1, 9, 9, 0, 0)
}, expanded);

var next = engine.NextOccurrence(job, new DateTime(2024, 1, 5, 12, 0, 0));

